FUNCTION_BLOCK FB
VAR_INPUT
    openBtn    : BOOL;
    closeBtn   : BOOL;
    openLimit  : BOOL;
    closeLimit : BOOL;
    obstacle   : BOOL;
END_VAR
VAR_OUTPUT
    motorUp    : BOOL;
    motorDown  : BOOL;
    errorFlag  : BOOL;
END_VAR
VAR
    state       : INT;  // 0=IDLE, 1=OPENING, 2=CLOSING, 3=FAULT
    prevOpen    : BOOL;
    prevClose   : BOOL;
    prevBoth    : BOOL;
    openRising  : BOOL;
    closeRising : BOOL;
    bothRising  : BOOL;
END_VAR

// 边沿检测
openRising  := openBtn AND NOT prevOpen;
closeRising := closeBtn AND NOT prevClose;
bothRising  := openBtn AND closeBtn AND NOT prevBoth;

// 初始化
IF state = 0 THEN
    motorUp   := FALSE;
    motorDown := FALSE;
    errorFlag := FALSE;
END_IF

// 状态机主逻辑
CASE state OF
    0:  // IDLE
        motorUp   := FALSE;
        motorDown := FALSE;
        IF openRising AND NOT openLimit THEN
            state := 1;
        ELSIF closeRising AND NOT closeLimit THEN
            state := 2;
        END_IF

    1:  // OPENING
        motorUp   := TRUE;
        motorDown := FALSE;
        IF obstacle AND NOT prevOpen THEN
            state := 3;
        ELSIF openLimit THEN
            state := 0;
        END_IF

    2:  // CLOSING
        motorUp   := FALSE;
        motorDown := TRUE;
        IF obstacle AND NOT prevClose THEN
            state := 1;
        ELSIF closeLimit THEN
            state := 0;
        END_IF

    3:  // FAULT
        motorUp   := FALSE;
        motorDown := FALSE;
        errorFlag := TRUE;
        IF bothRising THEN
            state := 0;
            errorFlag := FALSE;
        END_IF
END_CASE

// 更新历史状态
prevOpen  := openBtn;
prevClose := closeBtn;
prevBoth  := openBtn AND closeBtn;

END_FUNCTION_BLOCK
